config.script:
// Generated from Chrome DevTools Recorder flow "Acme login".
const page = browser.open();
function must(r, what) { if (!r.ok) { throw new Error(what + ": " + r.error); } }
function waitUrl(want) {
  var trim = function (u) { return String(u).replace(/\/$/, ""); };
  for (var i = 0; i < 10; i++) {
    if (trim(page.url()) === trim(want)) { return; }
    sleep(500);
  }
  throw new Error("expected navigation to " + want + " but the page is at " + page.url());
}
// step 1: setViewport 1280x720 ignored (the check uses a fixed viewport)
step("Go to \"https://app.acme.example/login\"", function () {
  must(page.goto("https://app.acme.example/login"), "step 2: navigate https://app.acme.example/login");
  waitUrl("https://app.acme.example/login");
});
step("Click \"Email\"", function () {
  must(page.click(["aria/Email", "#email", "xpath///*[@id=\"email\"]", "pierce/#email"]), "step 3: click Email");
});
step("Fill \"Email\"", function () {
  must(page.fill(["aria/Email", "#email"], "ops@acme.example"), "step 4: fill Email");
});
step("Click \"Password\"", function () {
  must(page.click(["aria/Password", "#password"]), "step 5: click Password");
});
step("Fill \"Password\"", function () {
  must(page.fill(["aria/Password", "#password"], secrets.RECORDER_SECRET_1), "step 6: fill Password");
});
step("Press \"Enter\"", function () {
  must(page.press(["aria/Password", "#password"], "Enter"), "step 7: press Enter");
  waitUrl("https://app.acme.example/dashboard");
});
step("Wait for element \"Welcome back\"", function () {
  must(page.waitFor(["aria/Welcome back", "h1.welcome"], { timeout: 8000 }), "step 9: waitForElement Welcome back");
});
// step 10: hover has no effect on a check and was skipped
return { status: "up", output: { url: page.url() } };
